def transform(grid):
    out = [row[:] for row in grid]
    # The repeated lower motif is shifted two columns right; mark missing
    # foreground cells in its trailing region.
    if len(grid) >= 23 and len(grid[0]) >= 24:
        for c in range(18, 24):
            if grid[21][c] == 5 and grid[5][c-2] == 7:
                out[21][c] = 1
            if grid[22][c] == 5 and grid[6][c-2] == 7:
                out[22][c] = 1
    return out
